import * as T from './vendor/three.module.js';
export function createSkateEffects(scene){
 const root=new T.Group();root.name='skate-ice-dust';scene.add(root);const count=100,positions=new Float32Array(count*3),alpha=new Float32Array(count),seeds=Array.from({length:count},()=>({until:0,x:0,z:0,vx:0,vz:0}));let cursor=0,carry=0;
 const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(positions,3));geometry.setAttribute('aLife',new T.BufferAttribute(alpha,1));const material=new T.ShaderMaterial({transparent:true,depthWrite:false,blending:T.AdditiveBlending,uniforms:{color:{value:new T.Color('#d9f6ff')}},vertexShader:'attribute float aLife;varying float life;void main(){life=aLife;vec4 p=modelViewMatrix*vec4(position,1.);gl_PointSize=clamp(50./-p.z,1.,8.)*aLife;gl_Position=projectionMatrix*p;}',fragmentShader:'uniform vec3 color;varying float life;void main(){float a=smoothstep(.5,.1,length(gl_PointCoord-.5))*life;gl_FragColor=vec4(color,a*.65);}'});const particles=new T.Points(geometry,material);particles.frustumCulled=false;root.add(particles);
 return{update({x,z,yaw,speed,active,brake,time,dt,still}){carry+=active&&!still&&speed>.5?dt*(brake?65:18):0;while(carry>=1){carry--;const s=seeds[cursor++%count],side=cursor%2?1:-1;s.x=x+Math.cos(yaw)*side*.28;s.z=z-Math.sin(yaw)*side*.28;s.vx=-Math.sin(yaw)*speed*.08+Math.cos(time*37)*.25;s.vz=-Math.cos(yaw)*speed*.08+Math.sin(time*29)*.25;s.until=time+.8;}for(let i=0;i<count;i++){const s=seeds[i],life=Math.max(0,s.until-time),t=.8-life;positions[i*3]=s.x+s.vx*t;positions[i*3+1]=.14+Math.sin(t/.8*Math.PI)*.12;positions[i*3+2]=s.z+s.vz*t;alpha[i]=life/.8;}geometry.attributes.position.needsUpdate=true;geometry.attributes.aLife.needsUpdate=true;}};
}
